import numpy as np
import matplotlib.pyplot as plt

# 1. Physics Principles Explained
# The Earth's magnetic field is primarily a dipole field, similar to that of a bar magnet.
# This field is generated by electric currents due to the motion of convection currents of molten iron in the Earth's outer core (the geodynamo theory).
# The magnetic field lines show the direction a compass needle would point. They emerge from the southern hemisphere and re-enter in the northern hemisphere.

# 2. Realistic Parameters
# Earth's magnetic dipole moment (approximate value in 2020)
M = 7.7e22  # A·m²
# Permeability of free space
mu_0 = 4 * np.pi * 1e-7  # T·m/A
# Earth's radius
R_E = 6371e3  # meters

# 3. Create a grid of points to calculate the magnetic field
nx, ny = 64, 64
x = np.linspace(-3 * R_E, 3 * R_E, nx)
y = np.linspace(-3 * R_E, 3 * R_E, ny)
X, Y = np.meshgrid(x, y)

# 4. Calculate the magnetic field components (B_x, B_y) at each point
# Using the dipole field equations in Cartesian coordinates
r = np.sqrt(X**2 + Y**2)
# We treat the dipole as being at the origin, aligned with the y-axis
# This is a simplification. The actual magnetic pole is tilted.
B_x = (mu_0 * M / (4 * np.pi)) * (3 * X * Y) / r**5
B_y = (mu_0 * M / (4 * np.pi)) * (3 * Y**2 - r**2) / r**5

# 5. Visualization
fig, ax = plt.subplots(figsize=(10, 8))

# Draw the Earth
earth = plt.Circle((0, 0), R_E, color='lightblue', zorder=5)
ax.add_artist(earth)

# Plot the magnetic field lines using streamplot
# We calculate the magnitude of the field for color coding
B_mag = np.sqrt(B_x**2 + B_y**2)
# Use logarithmic scale for color to better visualize variations
strm = ax.streamplot(X, Y, B_x, B_y, color=np.log10(B_mag), linewidth=1, cmap='viridis', density=2)

# Add a colorbar
cbar = fig.colorbar(strm.lines, ax=ax)
cbar.set_label('log10(Magnetic Field Strength [T])')

# Set plot title and labels
ax.set_title("Simulation of Earth's Magnetic Field (Dipole Model)")
ax.set_xlabel("Distance (meters)")
ax.set_ylabel("Distance (meters)")

# Set aspect ratio to be equal
ax.set_aspect('equal', 'box')

# Set limits to zoom in on the Earth
ax.set_xlim(-3 * R_E, 3 * R_E)
ax.set_ylim(-3 * R_E, 3 * R_E)

# Show the plot
plt.grid(True)
plt.show()
